n.loginUrl:
function login(){ doLogin(); }

// ===== 搜索模式切换（搜作品 / 搜作者）=====
function setSearchMode(m){
	source.put("searchMode", m);
	java.longToast(m == "author" ? "✅ 已切换到：搜作者（输入作者名）" : "✅ 已切换到：搜作品（作品名/CP/原作名）");
}


// ===== 读取登录输入 =====
function gv(m, k){
	var v = "";
	try{ var a = m[k]; if(a !== undefined && a !== null) v = String(a); }catch(e){}
	if(!v){ try{ var b = m.get(k); if(b !== undefined && b !== null) v = String(b); }catch(e2){} }
	return v;
}
function readAcc(){
	try{ java.upLoginData(); }catch(e){}
	var map = result;
	try{ if(!map) map = source.getLoginInfoMap(); }catch(e){}
	return {u: gv(map, "邮箱"), p: gv(map, "密码")};
}

// ===== 登录（邮箱+密码 → token）=====
function doLogin(){
	var r = readAcc();
	var email = String(r.u || "").trim();
	var pwd = String(r.p || "");
	if(!email || !pwd){ java.longToast("请先填写邮箱和密码"); return; }
	try{
		var body = "email=" + encodeURIComponent(email) + "&password=" + encodeURIComponent(pwd);
		var resp = String(java.post("https://api.newlucifer.com/s/User/login", body, {"Content-Type": "application/x-www-form-urlencoded"}).body() || "");
		var d = {}; try{ d = JSON.parse(resp); }catch(e){}
		if(d && d.code == 200 && d.data && d.data.token){
			source.put("token", String(d.data.token));
			if(d.data.nickname) source.put("nickname", String(d.data.nickname));
			if(d.data.uid) source.put("uid", String(d.data.uid));
			java.longToast("✅ 登录成功：" + (d.data.nickname || email));
		}else{
			source.put("token", "");
			java.longToast("⚠️ 登录失败：" + (d && d.msg ? d.msg : "未知错误"));
		}
	}catch(e){ java.longToast("登录失败：" + e); }
}

// ===== 注册账号（打开网站注册页）=====
function toRegister(){
	try{
		java.startBrowserAwait("https://slash.newlucifer.com/register", "注册露西弗同人站账号");
		java.longToast("注册完成后，请回到这里填写邮箱和密码登录");
	}catch(e){ java.longToast("打开注册页失败：" + e); }
}

// ===== 检查登录状态 =====
function checkLogin(){
	var tk = source.get("token") || "";
	if(!tk){ java.longToast("❌ 未登录：请填写邮箱和密码后点「👤 登录」"); return; }
	try{
		var resp = String(java.post("https://api.newlucifer.com/s/User/info", "token=" + encodeURIComponent(tk), {"Content-Type": "application/x-www-form-urlencoded"}).body() || "");
		var d = {}; try{ d = JSON.parse(resp); }catch(e){}
		if(d && d.code == 200 && d.data){
			var nm = source.get("nickname") || d.data.nickname || d.data.penname || d.data.email || "";
			java.longToast("✅ 已登录：" + (nm || "账号正常"));
		}else{
			source.put("token", "");
			java.longToast("❌ 登录已失效，请重新登录：" + (d && d.msg ? d.msg : ""));
		}
	}catch(e){ java.toast("检查登录状态失败：" + e); }
}

// ===== 退出登录 =====
function logoff(){
	try{
		var tk = source.get("token") || "";
		if(tk){ try{ java.post("https://api.newlucifer.com/s/User/logout", "token=" + encodeURIComponent(tk), {"Content-Type": "application/x-www-form-urlencoded"}); }catch(e){} }
		source.put("token", "");
		source.put("nickname", "");
		source.put("uid", "");
		java.toast("已退出登录");
	}catch(e){ java.toast("退出失败：" + e); }
}

// ===== 交流QQ群（点击申请入群）=====
function joinQQGroup(){
	var u = "mqqapi://card/show_pslcard?src_type=internal&version=1&card_type=group&uin=1097919737";
	try{
		java.openUrl(u);
		java.toast("已尝试打开QQ加群页面，若未跳转请手动搜索群号 1097919737");
	}catch(e){
		java.longToast("请手动在QQ中搜索群号 1097919737");
	}
}

ruleBookInfo.intro:
@js:
var o = {};
try{ o = JSON.parse(src || '{}'); }catch(e){}
var d = o.data || {};
var c = d.introduction || '';
if(d.warning){ c = c + '\n\n⚠️ 分级提示：' + d.warning; }

// ===== 书评（仿老站模式，分页抓取，最多100条）=====
var bid = (baseUrl.match(/article_id=(\d+)/) || [])[1];
var tk = source.get("token") || "";
var cmts = [];
var note = "";
try{
	if(bid){
		var p1 = String(java.ajax('https://api.newlucifer.com/s/Reader/comment_list,{"method":"POST","body":"article_id=' + bid + '&page=1&limit=100&token=' + tk + '"}') || '');
		var d1 = JSON.parse(p1);
		if(d1 && d1.data && d1.data.list){ cmts = cmts.concat(d1.data.list); }
		var tp = (d1 && d1.data && d1.data.pages) ? Number(d1.data.pages.total) : 1;
		if(tp > 1 && cmts.length < 100){
			var p2 = String(java.ajax('https://api.newlucifer.com/s/Reader/comment_list,{"method":"POST","body":"article_id=' + bid + '&page=2&limit=100&token=' + tk + '"}') || '');
			var d2 = JSON.parse(p2);
			if(d2 && d2.data && d2.data.list){ cmts = cmts.concat(d2.data.list); }
		}
		if(tp > 1){ note = ' / 共' + tp + '页'; }
	}
}catch(e){}
if(cmts.length < 1 && d.comment && d.comment.list){ cmts = d.comment.list; }
if(cmts.length){
	c = c + '\n\n💬 书评（显示' + cmts.length + '条' + note + '）：\n';
	for(var i = 0; i < cmts.length; i++){
		var cm = cmts[i];
		var nm = cm.nickname || cm.penname || '匿名';
		var tm = String(cm.create_date || '').replace(/\s+/, ' ');
		var ti = cm.title ? '《' + cm.title + '》' : '';
		c = c + '🌺 #' + (cm.floor || '') + ' ' + nm + ' 于' + tm + (ti ? ' 在' + ti : '') + '说：' + cm.content + '\n';
		// 回复（↳ 缩进显示）
		if(cm.reply_list && cm.reply_list.length){
			for(var j = 0; j < cm.reply_list.length; j++){
				var r = cm.reply_list[j];
				var rn = r.nickname || r.penname || '匿名';
				var rt = String(r.create_date || '').replace(/\s+/, ' ');
				c = c + '  ↳ ' + rn + ' 于' + rt + '回复：' + r.content + '\n';
			}
		}
	}
}
result = c;

